import{_ as o,o as t,c as e,a2 as r}from"./chunks/framework.A5mep7Fe.js";const g=JSON.parse('{"title":"🦾 01 · 具身智能（Embodied AI）","description":"","frontmatter":{},"headers":[],"relativePath":"05-算法岗-前沿与具身/01-具身智能.md","filePath":"05-算法岗-前沿与具身/01-具身智能.md","lastUpdated":1786806808000}'),i={name:"05-算法岗-前沿与具身/01-具身智能.md"};function n(l,a,s,d,h,c){return t(),e("div",null,[...a[0]||(a[0]=[r('<h1 id="🦾-01-·-具身智能-embodied-ai" tabindex="-1">🦾 01 · 具身智能（Embodied AI） <a class="header-anchor" href="#🦾-01-·-具身智能-embodied-ai" aria-label="Permalink to &quot;🦾 01 · 具身智能（Embodied AI）&quot;">​</a></h1><blockquote><p>让 AI 拥有「身体」——能感知物理世界、操控物体、完成真实任务。2024+ 最热的方向之一。</p></blockquote><hr><h2 id="一、核心命题" tabindex="-1">一、核心命题 <a class="header-anchor" href="#一、核心命题" aria-label="Permalink to &quot;一、核心命题&quot;">​</a></h2><p>智能不止在文本里，而在「与环境交互」中。具身智能 = <strong>感知（视觉/触觉）+ 决策（规划/RL）+ 执行（控制）</strong> 的闭环。</p><h2 id="二、技术路线" tabindex="-1">二、技术路线 <a class="header-anchor" href="#二、技术路线" aria-label="Permalink to &quot;二、技术路线&quot;">​</a></h2><ul><li><strong>VLA（Vision-Language-Action）模型</strong>：把视觉、语言指令、动作统一建模，大模型直接输出机器人动作（如 RT-1/2、OpenVLA）。</li><li><strong>Sim2Real</strong>：先在仿真训练，再迁移真实（解决真实数据稀缺）。</li><li><strong>模仿学习 / 遥操作</strong>：人类示范 → 模型学习策略。</li><li><strong>RL + 世界模型</strong>：在内部模型中预演，再执行。</li></ul><h2 id="三、关键挑战" tabindex="-1">三、关键挑战 <a class="header-anchor" href="#三、关键挑战" aria-label="Permalink to &quot;三、关键挑战&quot;">​</a></h2><ul><li><strong>数据</strong>：真实机器人数据极贵（远少于文本）</li><li><strong>Sim2Real gap</strong>：仿真与现实的差距</li><li><strong>泛化</strong>：新物体/新场景的适应能力</li><li><strong>安全</strong>：物理动作不可撤销</li></ul><h2 id="四、与大模型的关系" tabindex="-1">四、与大模型的关系 <a class="header-anchor" href="#四、与大模型的关系" aria-label="Permalink to &quot;四、与大模型的关系&quot;">​</a></h2><p>大模型提供「常识与语言理解」，机器人提供「执行」。具身是 AGI 的「行动出口」。</p><h2 id="五、高频追问" tabindex="-1">五、高频追问 <a class="header-anchor" href="#五、高频追问" aria-label="Permalink to &quot;五、高频追问&quot;">​</a></h2><p><strong>Q1：为什么具身智能难？</strong></p><blockquote><p>数据稀缺（远少于文本）、仿真到现实有 gap、物理安全约束强、长程任务难规划。大模型补了「脑」，但「手」仍是瓶颈。</p></blockquote><p><strong>Q2：VLA 是什么？</strong></p><blockquote><p>Vision-Language-Action 模型，把视觉输入+语言指令+动作空间统一训练，让大模型直接输出机器人控制信号，是当前主流范式。</p></blockquote><hr><p>➡️ 下一步：<a href="./02-自动驾驶">02-自动驾驶</a></p>',18)])])}const u=o(i,[["render",n]]);export{g as __pageData,u as default};
